const raw = $input.first().json;
const body = raw.body || raw;
const headers = raw.headers || {};

// 0. Seguridad (Punto 1): Validar secreto del webhook si esta configurado en entorno
const expectedSecret = ($env.EVOLUTION_WEBHOOK_SECRET || $env.WEBHOOK_SECRET || '').trim();
if (expectedSecret) {
  const incomingSecret = (headers['x-webhook-secret'] || headers['apikey'] || (headers['authorization'] || '').replace(/^Bearer\s+/i, '') || '').trim();
  if (incomingSecret !== expectedSecret) {
    return [];
  }
}

const rawEvent = (body.event || body.type || raw.event || raw.type || '').toString();
const eventLower = rawEvent.toLowerCase();
const instance = body.instance || raw.instance || '';

// 1. Descartar eventos de contactos o actualizaciones secundarias (evita disparar el bot)
if (eventLower.includes('contacts')) {
  return [];
}

// 2. Identificar tipos de eventos soportados
const isConnectionUpdate = (eventLower === 'connection.update' || eventLower === 'connection_update');
const isMessageUpsert = (eventLower === 'messages.upsert' || eventLower === 'messages_upsert');

// Descartar si no es conexion ni mensaje entrante
if (!isConnectionUpdate && !isMessageUpsert) {
  return [];
}

// Extraer objeto de datos
let data = body.data || raw.data || {};
if (Array.isArray(data)) {
  data = data[0] || {};
}

// 3. Extraer ID del mensaje para deduplicacion (evita reintentos de Evolution API)
const messageId = data.key?.id || body.key?.id || '';

if (isMessageUpsert && messageId) {
  try {
    const staticData = typeof $getWorkflowStaticData === 'function' ? $getWorkflowStaticData('global') : null;
    if (staticData) {
      staticData.seenMessageIds = staticData.seenMessageIds || {};
      const now = Date.now();
      for (const [id, time] of Object.entries(staticData.seenMessageIds)) {
        if (now - time > 120000) {
          delete staticData.seenMessageIds[id];
        }
      }
      if (staticData.seenMessageIds[messageId]) {
        return [];
      }
      staticData.seenMessageIds[messageId] = now;
    }
  } catch (e) {}
}

// Extraer remoteJid
const remoteJid = data.key?.remoteJid || body.key?.remoteJid || data.remoteJid || body.remoteJid || '';

// Filtrar grupos y transmisiones
const isGroupOrBroadcast = remoteJid.endsWith('@g.us') || remoteJid.includes('status@broadcast');

// Extraer y verificar si es mensaje propio (fromMe)
const rawFromMe = data.key?.fromMe ?? body.key?.fromMe ?? data.fromMe ?? body.fromMe;
const isFromMeRaw = rawFromMe === true || rawFromMe === 'true' || rawFromMe === 1;
const isFromMe = isFromMeRaw || isGroupOrBroadcast;

// Nombre de contacto
const pushName = data.pushName || body.pushName || 'Jugador';

// Extraer texto del mensaje de cualquier estructura de WhatsApp
let messageText = '';
if (data.message) {
  messageText = data.message.conversation ||
                data.message.extendedTextMessage?.text ||
                data.message.imageMessage?.caption ||
                data.message.videoMessage?.caption ||
                data.message.documentMessage?.caption ||
                '';
} else if (body.messageText) {
  messageText = body.messageText;
}

// Respuesta a menú interactivo (lista nativa o botones)
const listRowId = data.message?.listResponseMessage?.singleSelectReply?.selectedRowId ||
                  data.message?.buttonsResponseMessage?.selectedButtonId ||
                  data.message?.templateButtonReplyMessage?.selectedId ||
                  '';
if (!messageText && data.message?.listResponseMessage) {
  messageText = data.message.listResponseMessage.title || '';
}

// Extraer base64 de media si está presente
const mediaBase64 = data.message?.base64 || data.message?.imageMessage?.base64 || data.message?.documentMessage?.base64 || data.base64 || '';

// Detectar si es media (imagen/documento/comprobante)
const isImage = !!(data.message?.imageMessage || data.message?.documentMessage);

// DETECCIÓN (Punto 3): Cualquier interacción con texto, botones o comprobantes
// se procesa para que clientes en conversación activa nunca sean ignorados
const rawText = (messageText || '').trim();
const isInteractiveAction = !!listRowId;
const isMedia = isImage;
const hasContent = rawText.length > 0;

const isReservationCandidate = isInteractiveAction || isMedia || hasContent;

return {
  json: {
    rawEvent,
    instance,
    isConnectionUpdate,
    isMessageUpsert,
    isFromMe,
    remoteJid,
    pushName,
    messageText,
    isImage,
    listRowId,
    isReservationCandidate,
    messageId,
    mediaBase64,
    data
  }
};
